from fastapi import FastAPI, APIRouter

router1 = APIRouter()
router2 = APIRouter()

@router1.get('/path1')
def handler1():
    return {'msg': 'handler1'}

@router2.get('/path2')
def handler2():
    return {'msg': 'handler2'}

router1.include_router(router2)

# In 0.136.3, iterating router1.routes gives you all routes including nested ones
route_count = len([r for r in router1.routes if hasattr(r, 'path')])
assert route_count == 2, f"Expected 2 routes, got {route_count}"
